  (* [comment removed for export] *)
  Lemma pcm_C0 : forall regs m (s : Z),
    rdn SEGS m (Z_to_bv 64 0x38470) 8 = Some (Z_to_le_bytes 8 0x394e0) -> rdn SEGS m (Z_to_bv 64 0x394e0) 4 = Some (Z_to_le_bytes 4 3) ->
    getr regs 2 = Z_to_bv 64 (s - 48) -> getr regs 10 = Z_to_bv 64 0 ->
    exists regs',
      msteps SEGS (mkst regs (0x19868 : word) m rom) (mkst regs' (0x17ba4 : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 48) /\ getr regs' 1 = Z_to_bv 64 0x199bc
      /\ getr regs' 10 = Z_to_bv 64 0x10766 /\ getr regs' 11 = Z_to_bv 64 0x108d3 /\ getr regs' 12 = Z_to_bv 64 1
